INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ねぇねぇ、騎士クン\n手伝ってあげようよ～", 0, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 0, 1, 1001, 1, 0, 1.4, 0, 0, 1, 2, "春咲 ひより", "お！\nあそこに困ってそうな人発見！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("わ、わたし、\nなに言ってるんだろ\nあはは…", 0, "みんなみたいに\nわたしも強くならなきゃ", 0, 1, 1002, 1, 0, 1.4, 0, 0, 1, 2, "草野 優衣", "大切な人を\n守れるようになりたい…って");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("少しは磨かれると思いますよ。", 0, "フェンシングを始めてみては？", 0, 1, 1003, 1, 0, 1.4, 0, 0, 1, 2, "士条 怜", "キミに必要な集中力と感性が");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("みそぎはねぇ、\nかくれんぼやりたい！", 0, "ねぇ、にいちゃん！", 0, 1, 1004, 1, 0, 1.5, 0, 0, 1, 2, "穂高 みそぎ", "今日はなにして遊ぶ？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("私といっしょに…\nいかない？", 0, "風宮あかりです", 0, 1, 1006, 1, 0, 1.4, 0, 0, 1, 2, "風宮 あかり", "ねぇ…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("食べ物の恨みは怖いのー", 0, "出雲宮子なのー", 0, 1, 1007, 1, 0, 1.5, 0, 0, 1, 2, "出雲 宮子", "プリンたべたいのー");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("いいよ。\n見られることは運命さ…", 0, "ボクは虹村雪。", 0, 1, 1008, 1, 0, 1.4, 0, 0, 1, 2, "虹村 雪", "キミもボクの美貌に\n吸い寄せられたんだね。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("人呼んで「疾風の冥姫」!!", 0, "フッ…聞いて後悔するがいい！", 0, 1, 1009, 1, 0, 1.4, 0, 0, 1, 2, "柊杏奈", "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ほんまおおきにやわ～♪", 0, "マホマホ王国のプリンセス、\nまほ姫どす", 0, 1, 1010, 1, 0, 1.5, 0, 0, 1, 2, "姫宮 真歩", "うさぎさん、\n運命の王子はんに巡りあわせてくれて");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ここで会ったが\n100年目～！", 0, "衣之咲璃乃です！", 0, 1, 1011, 1, 0, 1.4, 0, 0, 1, 2, "衣之咲 璃乃", "生き別れたお兄ちゃんを探して\n三千世界！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("…って、お願い！\n誰にも言わないでおいて～！", 0, "私はハツネ、\n結構強いんだよ。\nきらーん☆", 0, 1, 1012, 1, 0, 1.4, 0, 0, 1, 2, "柏崎 初音", "ち、超能力って…\n何のことかな～？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ヒデサイまぢ\nGF（グッドフィーリング）～♪", 0, "ちょす！\n美波鈴奈だよ～♪", 0, 1, 1016, 1, 0, 1.4, 0, 0, 1, 2, "美波 鈴奈", "一応カリスマ読モJKやってまっす！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("でも、沖縄もとってもいいとこさー", 0, "はいたーい。\n喜屋武香織さー。", 0, 1, 1017, 1, 0, 1.4, 0, 0, 1, 2, "喜屋武 香織", "東京は遊園地みたいなところさー");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("イオちゃんって呼んでね。", 0, "支倉伊緒です。", 0, 1, 1018, 1, 0, 1.4, 0, 0, 1, 2, "支倉 伊緒", "先生って呼ばれるのは\nくすぐったいから");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ミミをおいてかないでぇ～", 0, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 0, 1, 1020, 1, 0, 1.5, 0, 0, 1, 2, "茜 ミミ", "あ！/\お兄ちゃ～ん\nまってよ～");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ふぇぇぇぇぇん……", 0, "あ…あの…えっと…\n栗…林…くるみ…です……", 0, 1, 1021, 1, 0, 1.5, 0, 0, 1, 2, "栗林 くるみ", "あの……\nふぇ……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("なんてありがとうございます！", 0, "風宮よりです。\nあああああ！", 0, 1, 1022, 1, 0, 1.4, 0, 0, 1, 2, "風宮 より", "こんな私に貴重な時間を\n割いていただき、");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("私こっち行きたいー\nね、早く早くー", 0, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 0, 1, 1023, 1, 0, 1.5, 0, 0, 1, 2, "北条 綾音", "おにいちゃんどこいくの？\nえ？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("これて何か違う…\nあああすみません！", 0, "わっ…わっ…私、\n天野すずめといいます！", 0, 1, 1025, 1, 0, 1.4, 0, 0, 1, 2, "天野 すずめ", "ふ、不束者ですが\nどうぞ末永く…って、");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("離しませんわ………\n絶対に…!!", 0, "……クスクス…私は\n…倉石恵理子……", 0, 1, 1027, 1, 0, 1.4, 0, 0, 1, 2, "倉石 恵理子", "あなたは…運命の……\n伴侶……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("…そうでしょ？？", 0, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 0, 1, 1028, 1, 0, 1.4, 0, 0, 1, 2, "佐々木 咲恋", "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("あはは、\n私もまだまだだなぁ～", 0, "桜井望だよ！\nよろしくねっ", 0, 1, 1029, 1, 0, 1.4, 0, 0, 1, 2, "桜井 望", "ぇっと…\nキミ、私のこと知らないの?!");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ショーグン、\nワタシと一緒に天下統一デース！", 0, "デケデケデンっ！", 0, 1, 1030, 1, 0, 1.4, 0, 0, 1, 2, "ニノン・ジュベール", "初めまして、\n私はニノン・ジュベール申すデス！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("おかしいですね……", 0, "上喜しのぶです。\n手元のドクロが父です。", 0, 1, 1031, 1, 0, 1.4, 0, 0, 1, 2, "上喜 しのぶ", "でもって私の隣にいるのが……\nえ、見えない？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("そう、\nオラのボケに突っ込める相方が…！", 0, "目指すはビッグな\nお笑い芸人だっぺ！", 0, 1, 1033, 1, 0, 1.5, 0, 0, 1, 2, "野戸まひる", "けんども\nそれには足りないモンが…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ちょ\nちょっと一杯飲んできます…！", 0, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 0, 1, 1034, 1, 0, 1.4, 0, 0, 1, 2, "綾瀬 ゆかり", "ちょっと緊張しちゃって…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("これ以上お話しすることは…\nないです！", 0, "氷川鏡華…です", 0, 1, 1036, 1, 0, 1.5, 0, 0, 1, 2, "氷川 鏡華", "知らない人とは話しちゃいけないので");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 0, "柏崎…栞です。", 0, 1, 1038, 1, 0, 1.4, 0, 0, 1, 2, "柏崎 栞", "……あ、アラーム。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("野に咲く花が、\n唯一の話相手です。", 0, "ふ、双葉碧です。", 0, 1, 1040, 1, 0, 1.4, 0, 0, 1, 2, "双葉 碧", "私、一人も友達がいなくて……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("そう思っています。", 0, "三角千歌です。", 0, 1, 1042, 1, 0, 1.4, 0, 0, 1, 2, "三角 千歌", "私の歌声で、\n皆さんが幸せになってくれたらいいなって…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("う、疑ってすまなかったな…", 0, "安芸真琴だ。", 0, 1, 1043, 1, 0, 1.4, 0, 0, 1, 2, "安芸 真琴", "あぁ？\nお前のそいつの仲間か？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 0, "わらわこそは夜を総べる者！", 0, 1, 1044, 1, 0, 1.4, 0, 0, 1, 2, "イリヤ・オーンスタイン", "生けとし生ける全ての者よ！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ｌク、クウカに何かご用ですか!?", 0, "そこで騎士は妖精を乱暴に……", 0, 1, 1045, 1, 0, 1.4, 0, 0, 1, 2, "遠見 空花", "ぐふふふふ……はっ！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("う～ん…\n猫ってホントに最高にゃ～♪", 0, "宮坂たまきにゃ♪\n猫はいいにゃよ？", 0, 1, 1046, 1, 0, 1.4, 0, 0, 1, 2, "宮坂たまき", "自由気ままで♪\n寝て遊んで、食べてケンカして…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("…と思ったら\nバイトの時間だ！\nまたあとでね！", 0, "大神美冬よ！", 0, 1, 1048, 1, 0, 1.4, 0, 0, 1, 2, "大神 美冬", "それでは早速クエストに…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("お姉ちゃんがぜ～んぶ\nやってあげるからね！", 0, "星野静流だよ！", 0, 1, 1049, 1, 0, 1.4, 0, 0, 1, 2, "星野静流", "クエストもバトルも\n掃除も洗濯も");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 0, "アタシは玉泉美咲。", 0, 1, 1050, 1, 0, 1.5, 0, 0, 1, 2, "玉泉美咲", "見ての通りの\nセクシー美少女で");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("？？？？", 0, "？？？", 0, 1, 1052, 1, 0, 1.4, 0, 0, 1, 2, "リマ", "？？？？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("そ、そこまでいうなら\nもらってやる", 0, "モニカ・ヴァイスヴィントだ。", 0, 1, 1053, 1, 0, 1.5, 0, 0, 1, 2, "モニカ・ヴァイスヴィント", "菓子でつろうなどと\n稚拙な策を……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("そ、そこまでいうなら\nもらってやる", 0, "モニカ・ヴァイスヴィントだ。", 0, 1, 1058, 1, 0, 1.5, 0, 0, 1, 2, "ペコリーヌ", "菓子でつろうなどと\n稚拙な策を……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("そ、そこまでいうなら\nもらってやる", 0, "モニカ・ヴァイスヴィントだ。", 0, 1, 1059, 1, 0, 1.5, 0, 0, 1, 2, "コッコロ", "菓子でつろうなどと\n稚拙な策を……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("そ、そこまでいうなら\nもらってやる", 0, "モニカ・ヴァイスヴィントだ。", 0, 1, 1060, 1, 0, 1.5, 0, 0, 1, 2, "キャル", "菓子でつろうなどと\n稚拙な策を……");
